"""저장된 최종 결과 Notebook 실행. 학습/추론 재실행 없음."""
from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import os,time
import nbformat as nb
from nbclient import NotebookClient
from src.common import *


def main():
    for key,path in [('JUPYTER_PATH','outputs/jupyter'),('JUPYTER_RUNTIME_DIR','outputs/jupyter/runtime'),('IPYTHONDIR','outputs/ipython'),('MPLCONFIGDIR','outputs/.mplconfig')]:os.environ[key]=str(ROOT/path)
    book=nb.v4.new_notebook()
    book.metadata['kernelspec']={'name':'phm2018-v3','display_name':'PHM2018 V3 (로컬)','language':'python'}
    blocks=[
      ('markdown','# 15 보호된 장비 그룹 검증과 최종 시간 Holdout\n\n장비별 별도 모델이 아닌 여러 장비의 공통 모델입니다. 그룹 검증에서는 학습01–06/검증07–08 장비를 분리하고 최종 시간 Holdout을 제외했습니다. 사전 규칙으로 B 최대가용 기준 모델과 두 숫자 임계값을 동결한 뒤 기존20대의 마지막20% 시간 구간을 한 번 예측했습니다.\n\n이 Notebook은 저장된 결과를 읽고 검증합니다. 모델 재학습·Holdout 재추론·임계값 탐색을 수행하지 않습니다. 두 운영점 모두 연구 결과이며 현장 운영 기준을 승인한 것은 아닙니다.'),
      ('code',"from pathlib import Path\nimport sys,json,hashlib\nimport numpy as np,pandas as pd\nfrom IPython.display import display,Image\nROOT=Path.cwd()\nif ROOT.name=='notebooks':ROOT=ROOT.parent\nsys.path.insert(0,str(ROOT))\nfrom src.common import TABLES,CFG\nassert Path(sys.executable).resolve()==Path(CFG['python']).resolve()\nOUT=ROOT/'outputs/stage6'\ndef table(n):return pd.read_parquet(TABLES/(n+'.parquet'))\ndef figure(n):display(Image(filename=str(ROOT/('outputs/figures/final_evaluation/'+n+'.png'))))\ndef readjson(p):return json.loads(p.read_text(encoding='utf-8'))\ndef sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()\nfrozen=readjson(OUT/'frozen_manifest.json')\naccess=readjson(OUT/'holdout_access.json')\nassert access['status']=='complete' and access['full_prediction_passes']==1\nassert not access['refit'] and not access['threshold_search']\nprint('실행 환경:',sys.executable,'| 최종 모델:',frozen['family'],'| Holdout 전체 추론:',access['full_prediction_passes'],'회')\nfigure('protected_split')"),
      ('markdown','## 1. 보호된 그룹 검증\n\n각 장비 앞80%의 기존 시간 train/validation 분할을 이용하고 각각 과거900/미래1800 raw guard를 유지했습니다.12대 학습/4대 validation입니다. 그룹 validation은 조기 종료와 임계값 선택에 사용했으므로 독립 시험이 아닙니다. 최대가용56개와 공통37개의 입력 가용 이벤트를 분리해 비교합니다. 기록 이벤트 분모는121개입니다.'),
      ('code',"runs=table('stage5_training_summary')\nassert len(runs)==6 and runs.device.eq('cuda:0').all()\nfor rid in runs.run_id:\n    config=readjson(ROOT/'outputs/stage5'/(rid+'_booster_config.json'))\n    assert config['learner']['generic_param']['device']=='cuda:0'\nchecks5=readjson(ROOT/'outputs/validation/stage5_checks.json')\nassert all(c['passed'] for c in checks5['checks'])\ndisplay(runs)\npoints5=table('stage5_budget_points')\ndisplay(points5[points5.budget_per_10000_raw.isin([5,10])][['run_id','budget_per_10000_raw','detected_events','available_events','recorded_events','alarm_episodes_per_10000_raw']])\nfigure('group_results')\nprint('동결 전 그룹 검사 통과:',len(checks5['checks']))"),
      ('markdown','## 2. 모델과 숫자 임계값 동결\n\n상한5/10 각각 시간·그룹 validation 중 낮은 기록 검출률을 취한 뒤 평균을 최대화하는 사전 규칙으로 B를 선택했습니다. 최종 모델은 기존 stage2의20대 시간 train 기준 모델입니다. 그룹 실험 모델을 최종 모델로 바꾼 것이 아니며 train+validation 재학습도 하지 않았습니다. 모든 동결 파일의 해시를 확인합니다.'),
      ('code',"from datetime import datetime\nassert datetime.fromisoformat(frozen['frozen_at_utc'])<datetime.fromisoformat(access['opened_at_utc'])\nassert sha(OUT/'frozen_manifest.json')==access['frozen_manifest_sha256']\nfor path,digest in frozen['sha256'].items():assert sha(ROOT/path)==digest,path\ndisplay(table('stage6_selection_ranking'))\ndisplay(table('stage6_selection_evidence'))\ndisplay(pd.DataFrame(frozen['operating_points']))\nfigure('selection')\nprint('동결 파일 SHA256:',len(frozen['sha256']),'개 일치 · 동결 이후 재학습 없음')"),
      ('markdown','## 3. 최종 Holdout의 두 고정 운영점\n\n7/194개와33/194개를 검출했습니다. 입력 가용91개 기준은7.7%/36.3%이지만 입력 없는103개 고장도 전체 기록 분모에 포함합니다. 실제 경보 부담은0.815/9.899회/관측 지지길이10,000 raw입니다. 이는 전체 경보 부담이며 확정 오경보율이나 시간당 수치가 아닙니다. 두 임계값은 Holdout을 보기 전에 정해졌습니다.'),
      ('code',"summary=table('stage6_holdout_summary')\nevents=table('stage6_holdout_events')\nepisodes=table('stage6_holdout_episodes')\npredictions=pd.read_parquet(OUT/'holdout_predictions.parquet')\nassert sha(OUT/'holdout_predictions.parquet')==access['prediction_sha256']\nassert sha(TABLES/'stage6_holdout_summary.parquet')==access['summary_sha256']\nassert len(summary)==len(frozen['operating_points'])==2\nfor point in frozen['operating_points']:\n    r=summary[summary.operating_point.eq(point['operating_point'])].iloc[0]\n    e=events[events.operating_point.eq(point['operating_point'])]\n    a=episodes[episodes.operating_point.eq(point['operating_point'])]\n    assert r.threshold==point['threshold']\n    assert int(e.detected.sum())==r.detected_events\n    assert int(e.available.sum())==r.available_events\n    assert a.anchors.sum()==predictions.score.ge(point['threshold']).sum()\ndisplay(summary[['operating_point','threshold','detected_events','recorded_events','available_events','recall_recorded','recall_available','alarm_episodes_per_10000_raw','median_lead_raw']])\ndisplay(table('stage6_holdout_uncertainty'))\nfigure('holdout_results')"),
      ('markdown','## 4. 장비별·경보별 부담과 라벨 불확실성\n\n미확인 구간 시작 경보는 낮은 설정97.4%, 높은 설정94.5%입니다. NA를 정상이나 확정 오경보로 간주하지 않습니다. 알려진 라벨32,645행의 AP/ROC-AUC는 일부 정답이 확인된 분포에만 해당합니다. 군집 부트스트랩95% 구간은 장비쌍10개에 조건부이며 후보 선택이나 누락 편향을 보정하지 않습니다.'),
      ('code',"metrics=readjson(OUT/'holdout_classification.json')\nknown=predictions.audit_label.isin([0,1])\nassert int(known.sum())==metrics['known_anchors']\nassert int(predictions.audit_label.eq(1).sum())==metrics['positive']\ndisplay(metrics)\ndisplay(table('stage6_holdout_by_tool'))\nfigure('unknown_burden')\nfigure('by_tool')\nfigure('lead_resources')"),
      ('markdown','## 5. 저장된 예측과 실제 센서의 사례\n\n상한10 기준 검출 선행시간 중앙값에 가장 가까운 사례와 Tool/시각 순 첫 입력 가용 미검출 고장입니다. 사후 설명용 선정이며 모델/임계값에 반영하지 않습니다. 두 센서와 기존 점수만 표시하며 공백과 세그먼트 경계에서 선을 끊습니다.'),
      ('code',"cases=readjson(OUT/'case_examples.json')\nfor c in cases:\n    e=events[events.event_id.eq(c['event_id'])&events.operating_point.eq('validation_budget_10')].iloc[0]\n    assert bool(e.detected)==c['detected'] and e.fault_time==c['fault_time']\ndisplay(pd.DataFrame([{k:v for k,v in c.items() if k!='query'} for c in cases]))\nfigure('event_cases')"),
      ('markdown','## 6. 복구 이력·최종 검사와 결론\n\n첫736,646행 추론을 저장한 뒤 빈 장비 이벤트 표의 concat으로 bool 열이 object가 되어 집계가 실패했습니다. 동결 소스/모델/임계값은 보존하고 별도 스크립트에서 저장 결과의 bool 자료형만 변환해 집계를 복구했습니다. 추가 추론0회입니다. 원래 실패 로그와 복구 해시를 아래에서 확인합니다.\n\n현재는 연구 기준선으로 보존합니다. 입력 공백·미확인 이력·약한 장비 일반화가 해결되지 않아 자동 운영에 충분한 근거가 아닙니다. 후속 개선은 새 검증 데이터를 확보한 뒤 평가해야 합니다. 이번 구간을 반복 튜닝 후 독립 Holdout으로 재사용하지 않습니다. 초기 원본/전처리 품질 진단은 전 기간을 봤으므로 완전 맹검 외부 시험은 아닙니다.'),
      ('code',"recovery=readjson(OUT/'postprocessing_recovery.json')\nassert recovery['postprocessing_only'] and recovery['additional_prediction_passes']==0\nassert recovery['input_prediction_sha256']==sha(OUT/'holdout_predictions.parquet')\nassert recovery['original_failure_log_sha256']==sha(ROOT/'outputs/stage6_holdout_evaluation.log')\nassert recovery['recovery_script_sha256']==sha(ROOT/'scripts/recover_stage6_postprocessing.py')\nchecks6=readjson(ROOT/'outputs/validation/stage6_checks.json')\nassert all(c['passed'] for c in checks6['checks']) and checks6['full_prediction_passes']==1\nassert checks6['frozen_files_unchanged'] and checks6['no_reselection']\nprint('Holdout 실제 결과 검사:',len(checks6['checks']),'PASS')\nprint('이 Notebook: 기존 예측·표·그림 검증만 실행, 모델 추론 0회')\ndisplay(recovery)")
    ]
    book.cells=[nb.v4.new_code_cell(t) if k=='code' else nb.v4.new_markdown_cell(t) for k,t in blocks]
    path=ROOT/'notebooks/15_final_holdout.ipynb';nb.write(book,path);started=time.monotonic()
    NotebookClient(book,timeout=300,kernel_name='phm2018-v3',resources={'metadata':{'path':str(ROOT)}}).execute();nb.write(book,path)
    cells=[c for c in book.cells if c.cell_type=='code'];errors=[o for c in cells for o in c.outputs if o.output_type=='error']
    result=dict(notebook='15_final_holdout',code_cells=len(cells),executed=sum(c.execution_count is not None for c in cells),errors=len(errors),elapsed_seconds=time.monotonic()-started,python=CFG['python'],additional_holdout_inference=0)
    dump_json(ROOT/'outputs/validation/final_notebook.json',result);print(result)


if __name__=='__main__':main()
